WITH pares AS (SELECT * FROM UNNEST([STRUCT('PA-1506187-94551B72659E427F961D2F62CEBA7392' alvo_id,'PA-1506187-878F5B604D8E471F8DE7F692F7F7288C' vizinho_id),('PA-1506187-CEAD1A3AC3E14F5DB2FC0B93E54E7E98','PA-1506187-3F4B7241FA0D4F60B91CCE115953FD56'),('PA-1506187-CEAD1A3AC3E14F5DB2FC0B93E54E7E98','PA-1506187-48EDE9CDCF3947959921871671228876'),('MS-5006606-4693892971CF47B4B2684C3A94950BEE','MS-5006606-9F4376C099A342D2899444A8DB7FADE6'),('MS-5006606-4693892971CF47B4B2684C3A94950BEE','MS-5006606-F52D5261C8504529A0FC680C01132DA2'),('BA-2921401-9177991E4861442EACDDC06DB91','BA-2921401-0F05B7015F404007905C0A598A258AF4'),('BA-2929057-C5D11EE026A64399A6EF36764E8739E9','BA-2929057-43362B5DD011494FA6B0EE05C2761D93)])]),a AS (SELECT * FROM `basedosdados.br_sfb_sicar.area_imovel` WHERE data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY id_imovel ORDER BY data_extracao DESC)=1) SELECT p.alvo_id,p.vizinho_id,a.area alvo_area_ha,v.area vizinho_area_ha,ST_WITHIN(a.geometria,v.geometria) alvo_100pct_dentro,SAFE_DIVIDE(ST_AREA(ST_INTERSECTION(a.geometria,v.geometria)),10000) intersecao_ha,SAFE_MULTIPLY(SAFE_DIVIDE(ST_AREA(ST_INTERSECTION(a.geometria,v.geometria)),ST_AREA(a.geometria)),100) percentual_alvo_na_intersecao FROM pares p JOIN a USING(id_imovel) JOIN a v ON v.id_imovel=p.vizinho_id